            if url not in found or s > found[url].score:
                found[url] = Candidate(url, s, lastmod or found.get(url, Candidate(url, 0)).lastmod, via)

        add(company.site_url, "homepage", score=9)
        prefixes = {"/", _locale_prefix(company.site_url)}
