    is_current = bool(current) and newest_current > newest_former if former else bool(current)
    if former and current:
        note = "sources disagree on whether this role is current"

    if (
        is_current
        and seniority == "c_level"
        and proxy_date
        and key not in person_in_proxy_keys
        and not any(c.doc.source_type == "sec_filing" for c in current)
        and newest_current < _ordinal(proxy_date)
    ):
