    best = supporting[0]
    dated = [c.published_at for c in supporting if c.published_at]
    as_of = max(dated) if dated else None
    confidence = _confidence(supporting)
    single = len({c.doc.url for c in supporting}) == 1
    if is_current and single and as_of and (today - date.fromisoformat(as_of)).days > (
        STALE_AFTER_DAYS
    ):
        confidence = "low"
        note = note or f"single source, last dated {as_of} (older than 18 months)"
    title = best.title
    if key[0] == "founder" and best.title_class.seniority != "founder":
        title = best.title  # e.g. "Co-founder & CEO"; the founder role shares the title fact
    return ResolvedRole(title, function, seniority, is_current, as_of, confidence, claims, note)


def resolve_claims(
    claims: list[Claim], today: date | None = None, company_id: int = 0
