    if function is None or seniority not in (None, "c_level"):
        return []
    out = []
    for p in people:
        current = [r for r in p["roles"] if r["is_current"]]
        if p["full_name"] in listed or not current:
            continue
        hits = [
            g for g in _grouped_titles(p)
            if g["presented_as_current"] and function in seat_functions(g["wording"])
        ]  # fmt: skip
        if hits:
            out.append(
