        ]  # fmt: skip
        if hits:
            out.append(
                {
                    "name": p["full_name"],
                    "resolved_current_roles": [_role(r) for r in current],
                    "wordings_naming_this_seat": hits,
                    "flags": _flags(p["full_name"] and "", p["full_name"]) if False else [],
                }
            )
    return out


