    stems = {company.name}
    for host in (company.domain, urlsplit(company.site_url).hostname or ""):
        stem = host.lower().removeprefix("www.").split(".")[0]
        if len(stem) >= 3:
            stems.add(stem)
    return {norm_text(s).casefold() for s in stems if s.strip()}


